// Mint's icons: filled paths on a 24 grid, as mint-pocs carries them, plus
// the few mint-pocs draws on the same grid in 2px round strokes where Mint
// has none. Copied path for path from mint-pocs' Sidebar and Transactions:
// an approximation shows next to the real ones. Decorative: the control
// around an icon names it.

import type { ReactNode } from "react";

export type IconProps = {
  /** The rendered size in px; the grid stays 24. */
  readonly size?: number;
  readonly className?: string;
};

type FilledProps = IconProps & {
  /** The solid twin, for the current page. */
  readonly filled?: boolean;
};

function Glyph({
  size = 20,
  className,
  children,
}: IconProps & { readonly children: ReactNode }) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

// mint-pocs' drawn icons: 2px strokes with round ends, Mint's weight
function Line({
  size = 20,
  className,
  children,
}: IconProps & { readonly children: ReactNode }) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

