/** Home: a house, its door cut out when current. */
export function HomeIcon({ filled = false, ...props }: FilledProps) {
  return (
    <Glyph {...props}>
      {filled ? (
        <path d={HOME_OUTER + HOME_DOOR} fillRule="evenodd" />
      ) : (
        <path d={HOME_INNER + HOME_OUTER} />
      )}
    </Glyph>
  );
}

/** Accounts: Mint's holdings dashboard, a board with its lines. */
export function AccountsIcon({ filled = false, ...props }: FilledProps) {
  return (
    <Glyph {...props}>
      <path
        d={
          filled
            ? BOARD_OUTER + BOARD_LINES
            : BOARD_OUTER + BOARD_INNER + BOARD_LINES
        }
        fillRule="evenodd"
      />
    </Glyph>
  );
}

/** Activity: a clock; the transactions, as they happen. */
export function ActivityIcon({ filled = false, ...props }: FilledProps) {
  return (
    <Glyph {...props}>
      <path
        d={
          filled
            ? CLOCK_OUTER + CLOCK_HANDS
            : CLOCK_OUTER + CLOCK_INNER + CLOCK_HANDS
        }
        fillRule="evenodd"
      />
    </Glyph>
  );
}

